command:
perl -0pi -e '
s/title: "POS Accessories CLI System",/title: "POS Accessories CLI System",\n    slug: "pos-accessories-cli",/;
s/title: "Elevator Visual & Analyze",/title: "Elevator Visual & Analyze",\n    slug: "elevator-visual-analyze",/;
s/title: "LDPlayer Automation Tool",/title: "LDPlayer Automation Tool",\n    slug: "ldplayer-automation",/;
s/title: "ArtiFlow Article Management",/title: "ArtiFlow Article Management",\n    slug: "artiflow-article-management",/;
s/title: "Joy Journal Daily",/title: "Joy Journal Daily",\n    slug: "joy-journal-daily",/;
s/title: "GrimHill",/title: "GrimHill",\n    slug: "grimhill",/;
s/href="\/NHEB_Tinarith_CV\.docx"/href={\`\${import.meta.env.BASE_URL}NHEB_Tinarith_CV.docx\`}/;
s/\Q                  <img
                    src={p.image}
                    alt={p.title}
                    className="w-full h-56 md:h-full object-cover"
                  />\E/                  <ProjectImage slug={p.slug} alt={p.title} fallback={p.image} \/>/;
s/\Qfunction Projects() {\E/my $c = <<"ENDCOMP";
function ProjectImage({ slug, alt, fallback }: { slug: string; alt: string; fallback: string }) {
  const [stage, setStage] = useState<"local" | "stock" | "empty">("local");
  if (stage === "empty") {
    return (
      <div
        aria-label={alt}
        className="w-full h-56 md:h-full bg-gradient-to-br from-purple-100 via-[#F0EDFF] to-indigo-100"
      />
    );
  }
  return (
    <img
      src={stage === "local" ? \`\${import.meta.env.BASE_URL}screenshots/\${slug}.png\` : fallback}
      alt={alt}
      onError={() => setStage(stage === "local" ? "stock" : "empty")}
      className="w-full h-56 md:h-full object-cover"
    />
  );
}

ENDCOMP
$c . "function Projects() {"/;
' src/App.tsx && echo "slug count:" && rg -c "slug:" src/App.tsx && rg -c "ProjectImage" src/App.tsx && rg -c "BASE_URL" src/App.tsx

cat > .tmp-comp.txt <<'EOF'
function ProjectImage({ slug, alt, fallback }: { slug: string; alt: string; fallback: string }) {
  const [stage, setStage] = useState<"local" | "stock" | "empty">("local");
  if (stage === "empty") {
    return (
      <div
        aria-label={alt}
        className="w-full h-56 md:h-full bg-gradient-to-br from-purple-100 via-[#F0EDFF] to-indigo-100"
      />
    );
  }
  return (
    <img
      src={stage === "local" ? `${import.meta.env.BASE_URL}screenshots/${slug}.png` : fallback}
      alt={alt}
      onError={() => setStage(stage === "local" ? "stock" : "empty")}
      className="w-full h-56 md:h-full object-cover"
    />
  );
}
EOF
sed -i 's/title: "POS Accessories CLI System",/title: "POS Accessories CLI System",\n    slug: "pos-accessories-cli",/; s/title: "Elevator Visual & Analyze",/title: "Elevator Visual \& Analyze",\n    slug: "elevator-visual-analyze",/; s/title: "LDPlayer Automation Tool",/title: "LDPlayer Automation Tool",\n    slug: "ldplayer-automation",/; s/title: "ArtiFlow Article Management",/title: "ArtiFlow Article Management",\n    slug: "artiflow-article-management",/; s/title: "Joy Journal Daily",/title: "Joy Journal Daily",\n    slug: "joy-journal-daily",/; s/title: "GrimHill",/title: "GrimHill",\n    slug: "grimhill",/' src/App.tsx
sed -i 's|href="/NHEB_Tinarith_CV\.docx"|href={`${import.meta.env.BASE_URL}NHEB_Tinarith_CV.docx`}|' src/App.tsx
sed -i '/^[[:space:]]*<img$/,/^[[:space:]]*\/>$/c\                  <ProjectImage slug={p.slug} alt={p.title} fallback={p.image} />' src/App.tsx
printf '\n' >> src/App.tsx && cat .tmp-comp.txt >> src/App.tsx && rm .tmp-comp.txt
echo "=== verify ==="; rg -c 'slug: "' src/App.tsx; rg -c 'ProjectImage' src/App.tsx; rg -c 'BASE_URL' src/App.tsx; rg -n 'src=\{p.image\}' src/App.tsx || echo "old img wiring gone"
